    /** Relax branches against actual page layouts, never against guessed offsets.
     * Shrinking a branch can move its target across a page boundary. Such a branch
     * is pinned to the far form before another pass, so relaxation cannot oscillate.
     * This runs only in the offline assembler; the guest receives ordinary bytecode.
     */
    static Compilation assembleOptimized(java.util.function.Consumer<Asm> program) {
        Set<Integer> local=new HashSet<>(),farOnly=new HashSet<>();int baseline=0;
        for(int pass=1;pass<=4096;pass++) {
            Asm s=new Asm(local);program.accept(s);byte[] image=s.finish();
            if(pass==1)baseline=image.length;
            Set<Integer> next=new HashSet<>(local);
            int jumps=0,conditions=0,far=0;
            for(Asm.Branch branch:s.branches) {
                boolean samePage=s.labels.get(branch.target())/256==branch.page();
                if(branch.local()&&!samePage){farOnly.add(branch.id());next.remove(branch.id());}
                else if(samePage&&!farOnly.contains(branch.id()))next.add(branch.id());
                if(branch.local()){if(branch.conditional())conditions++;else jumps++;}else far++;
            }
            if(next.equals(local)){if(s.codePages>128)throw new IllegalStateException("Desktop instructions overlap workspace");if(image.length>34816)throw new IllegalStateException("Desktop code overlaps application workspace: "+image.length/256+" pages");return new Compilation(image,baseline,pass,jumps,conditions,far); }
            local=next;
        }
        throw new IllegalStateException("Desktop branch layout did not converge");
    }
